import { useEffect, useId, useRef, useState } from 'react';
import toast from 'react-hot-toast';
import { fetchSample, fetchSampleQC, fetchSampleHistory, SAMPLE_TYPES, SAMPLE_STATUSES, SAMPLE_TRANSITIONS, QC_DECISIONS, qcBadge, updateSample, uploadSampleEvidence } from '../../lib/vendor-sampling';
import { formatFollowupTime } from '../../lib/vendor-followup-helpers';
import SampleEvidence from './SampleEvidence';
import SampleFormModal from './SampleFormModal';
import SampleQCModal from './SampleQCModal';
import SampleStatusModal from './SampleStatusModal';

export default function SampleDetailModal({ id, canSamples, canQC, canWriteSamples, canWriteQC, readOnly, options, profileId, onClose, onChanged, onRelated }) {
  const ref = useRef(null), pending = useRef(false), prefix = useId();
  const [sample, setSample] = useState(null), [runs, setRuns] = useState([]), [history, setHistory] = useState([]), [loading, setLoading] = useState(true), [error, setError] = useState(''), [version, setVersion] = useState(0);
  const [edit, setEdit] = useState(false), [status, setStatus] = useState(false), [qc, setQC] = useState(null), [busy, setBusy] = useState(false), [file, setFile] = useState(null), [uploadedPath, setUploadedPath] = useState('');
  useEffect(() => { const d = ref.current; d.showModal(); return () => d.close(); }, []);
  useEffect(() => { let ignore = false; setLoading(true); setError(''); Promise.all([fetchSample(id, canQC), canQC ? fetchSampleQC(id) : Promise.resolve([]), canSamples ? fetchSampleHistory(id) : Promise.resolve([])]).then(([s, r, h]) => { if (!ignore) { setSample(s); setRuns(r); setHistory(h); } }).catch((err) => { if (!ignore) setError(err.message); }).finally(() => { if (!ignore) setLoading(false); }); return () => { ignore = true; }; }, [id, canQC, canSamples, version]);
  const changed = () => { setEdit(false); setStatus(false); setQC(null); setVersion((n) => n + 1); onChanged(); };
  const action = async (fn) => { if (pending.current) return; pending.current = true; setBusy(true); setError(''); try { await fn(); changed(); } catch (err) { setError(err.message); } finally { pending.current = false; setBusy(false); } };
  const locked = readOnly || Boolean(sample?.candidate_archived_at);
  return <dialog ref={ref} aria-labelledby={prefix + 'title'} onCancel={(e) => { e.preventDefault(); if (!busy) onClose(); }} className="m-auto w-[calc(100%-2rem)] max-w-5xl max-h-[90vh] overflow-y-auto rounded-xl border border-white/10 bg-ink-900 text-white p-5 backdrop:bg-black/70">
    <div className="flex flex-wrap justify-between items-start gap-3"><div><h2 id={prefix + 'title'} className="text-lg font-semibold">Detail Sampel</h2>{sample && <p className="text-sm text-ink-400 mt-1">{sample.sample_code} · {sample.business_name}</p>}</div><button className="btn-secondary" disabled={busy} onClick={onClose}>Tutup sampel</button></div>
    {loading ? <p role="status" className="p-6 text-ink-400">Memuat sampel dan riwayat…</p> : sample && <div className="space-y-5 mt-5">
      {locked && <p className="badge-gray">Arsip · hanya dapat dilihat</p>}
      <div className="card p-4 space-y-3"><div className="flex flex-wrap justify-between items-center gap-3"><span className="badge-blue">{SAMPLE_STATUSES[sample.status]}</span><div className="flex flex-wrap gap-2">{canWriteSamples && !locked && <><button className="btn-secondary text-xs" onClick={() => setEdit(true)}>Edit Sampel</button>{SAMPLE_TRANSITIONS[sample.status]?.length > 0 && <button className="btn-primary text-xs" onClick={() => setStatus(true)}>Perbarui Status</button>}<button className="btn-secondary text-xs" onClick={() => onRelated(sample)}>Sampel Terkait Baru</button></>}{canWriteQC && !locked && sample.status === 'SAMPEL_DITERIMA' && <button className="btn-primary text-xs" disabled={busy} onClick={() => action(() => updateSample(sample, { status: 'SEDANG_QC' }))}>Mulai QC</button>}{canWriteQC && !locked && sample.status === 'SEDANG_QC' && <button className="btn-primary text-xs" onClick={() => setQC({})}>Catat Hasil QC</button>}</div></div>
        <div className="grid sm:grid-cols-3 gap-3 text-sm"><p><span className="text-ink-400 block text-xs">Jenis / produk</span>{SAMPLE_TYPES[sample.sample_type]} · {sample.product_code || 'Tanpa kode produk'}</p><p><span className="text-ink-400 block text-xs">Jumlah / bahan</span>{sample.quantity} {sample.unit} · {sample.material_source}</p><p><span className="text-ink-400 block text-xs">Target / PIC</span>{sample.target_date || 'Belum ditetapkan'} · {options.users.find((u) => u.id === sample.internal_pic_id)?.full_name || 'Belum ditugaskan'}</p></div>
        <p className="text-sm whitespace-pre-wrap break-words">{sample.brief}</p>{sample.notes && <p className="text-sm text-ink-400 whitespace-pre-wrap">{sample.notes}</p>}
        {sample.related_sample_id && <p className="text-xs text-ink-400">Memiliki hubungan dengan sampel sebelumnya. Riwayat sampel lama tetap dipertahankan.</p>}
        {canSamples && <SampleEvidence path={sample.techpack_path} label="Buka techpack privat" />}
        {canWriteSamples && !locked && Number(sample.qc_count) === 0 && <form className="space-y-2" onSubmit={(e) => { e.preventDefault(); action(async () => { const path = uploadedPath || await uploadSampleEvidence(sample, file); setUploadedPath(path); await updateSample(sample, { techpack_path: path }); setFile(null); setUploadedPath(''); toast.success('Techpack tersimpan'); }); }}><label className="label" htmlFor={prefix + 'techpack'}>Techpack PDF (maksimal 5 MB)</label><input id={prefix + 'techpack'} type="file" accept="application/pdf" className="input" disabled={busy} onChange={(e) => { setFile(e.target.files?.[0] || null); setUploadedPath(''); }} /><button className="btn-secondary text-xs" disabled={busy || !file}>Simpan Techpack</button></form>}
      </div>
      {canQC && <section className="space-y-3"><h3 className="font-semibold">Putaran QC ({runs.length})</h3><p className="text-xs text-ink-400">Hasil pemeriksaan tidak otomatis menyetujui atau mengaktifkan vendor.</p>{runs.length === 0 && <p className="card p-4 text-sm text-ink-400">Belum ada hasil QC untuk sampel ini.</p>}{runs.map((r) => <article key={r.id} className="card p-4 space-y-3">
        <div className="flex flex-wrap justify-between items-start gap-2"><div><h4 className="font-medium">Putaran {r.run_no} · {r.qc_code}</h4><p className="text-xs text-ink-400 mt-1">Pemeriksa: {r.inspector_name} · {formatFollowupTime(r.inspected_at)}</p><p className="text-xs text-ink-500">Diinput {r.input_user?.full_name || 'Pengguna tersimpan'} · {formatFollowupTime(r.input_at)}</p></div><div className="flex flex-wrap items-center gap-2"><span className={qcBadge(r.decision)}>{QC_DECISIONS[r.decision]}</span><span className="text-sm">{r.avg_score} / 5 · batas {r.pass_mark}</span>{canWriteQC && !locked && <button className="btn-secondary text-xs" onClick={() => setQC(r)}>Koreksi putaran {r.run_no}</button>}</div></div>
        <div className="grid sm:grid-cols-2 gap-2">{r.parameter_snapshot.map((p) => <p key={p.id} className="text-xs text-ink-300">{p.name}: <strong>{r.parameter_scores[p.id]}</strong> · bobot {p.weight}</p>)}</div>
        {r.findings && <p className="text-sm whitespace-pre-wrap">Temuan: {r.findings}</p>}{r.required_fixes && <p className="text-sm whitespace-pre-wrap">Perbaikan: {r.required_fixes} · batas {r.revision_due}</p>}{r.reinspection_note && <p className="text-sm text-ink-400">Pemeriksaan ulang: {r.reinspection_note}</p>}{r.notes && <p className="text-sm text-ink-400">{r.notes}</p>}
        <SampleEvidence path={r.document_path} label="Buka dokumen QC privat" /><div className="grid sm:grid-cols-3 gap-3">{r.photos.map((p, i) => <SampleEvidence key={p.path} path={p.path} image label={p.caption || `Bukti pemeriksaan ${i + 1}`} />)}</div>
        {r.revisions?.length > 0 && <details className="text-xs text-ink-400"><summary className="cursor-pointer">Riwayat koreksi ({r.revisions.length})</summary>{[...r.revisions].sort((a, b) => a.id - b.id).map((v) => <div key={v.id} className="mt-3 border-l border-white/10 pl-3 space-y-1"><p>{v.editor?.full_name || 'Pengguna tersimpan'} · {formatFollowupTime(v.edited_at)}</p><p className="text-ink-200 whitespace-pre-wrap">{v.edit_reason}</p><p>Hasil {QC_DECISIONS[v.old_values.decision]} → {QC_DECISIONS[v.new_values.decision]} · nilai {v.old_values.avg_score} → {v.new_values.avg_score}</p><p>Pemeriksa: {v.old_values.inspector_name} → {v.new_values.inspector_name}</p><SampleEvidence path={v.old_values.document_path} label="Dokumen sebelum koreksi" />{(v.old_values.photos || []).map((p) => <SampleEvidence key={p.path} path={p.path} label="Foto sebelum koreksi" />)}</div>)}</details>}
      </article>)}</section>}
      {canSamples && <details className="card p-4 text-xs text-ink-400"><summary className="cursor-pointer">Riwayat sampel ({history.length})</summary>{history.map((h) => <div key={h.id} className="mt-3 pl-3 border-l border-white/10 space-y-1"><p>{h.actor?.full_name || 'Pengguna tersimpan'} · {formatFollowupTime(h.changed_at)}</p><p>{h.old_values ? `${SAMPLE_STATUSES[h.old_values.status]} → ` : ''}{SAMPLE_STATUSES[h.new_values.status]}</p>{h.new_values.revision_note && <p className="whitespace-pre-wrap">{h.new_values.revision_note}</p>}<p className="whitespace-pre-wrap">Brief: {h.new_values.brief}</p></div>)}</details>}
    </div>}
    {error && <p role="alert" className="my-3 text-danger-400 text-sm">{error} <button className="underline" onClick={() => setVersion((n) => n + 1)}>Muat ulang</button></p>}
    {edit && sample && <SampleFormModal editing={sample} options={options} onClose={() => setEdit(false)} onSaved={changed} />}
    {status && sample && <SampleStatusModal sample={sample} options={options} profileId={profileId} onClose={() => setStatus(false)} onSaved={changed} />}
    {qc && sample && <SampleQCModal sample={sample} editing={qc.id ? qc : null} options={options} onClose={() => setQC(null)} onSaved={changed} />}
  </dialog>;
}
